(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["co"] = {"ui":{"skip":"Andà à u cuntenutu","back":"← Torna à AI-gile","lang.button":"Lingua: {name}","lang.dialog":"Sceglie una lingua","lang.search":"Circà lingue","lang.none":"Nisuna lingua currisponde","lang.notYet":"{name} ùn hè ancu traduttu","theme.aria":"Passà trà u tema chjaru è u tema scuru","theme.toLight":"Passà à u tema chjaru","theme.toDark":"Passà à u tema scuru","words.underline":"Sottulineà ste parolle nantu à a pagina","words.underlineHelp":"Passa sopra o tocca una parolla puntighjata per vede ciò ch'ella vole dì.","index.title":"AI-gile: a to squadra di sviluppu AI, nantu à una sola tavula","index.description":"AI-gile hè una tavula kanban per e squadre AI chì prugrammanu. Travaglianu mentre dorme; tù ricevi un picculu mucchjettu di cose à decide, pruvà è accettà.","hero.logoAlt":"Icona di a tavula AI-gile","hero.h1.html":"A to squadra di sviluppu AI, nantu à una sola&nbsp;tavula.","hero.alpha":"🐣 Pre-alfa chjosa","hero.alphaTitle":"Prestu è micca compiu: grazie di pruvallu!","hero.lede":"Custruiscenu mentre dorme. Ti svegli cù un mucchjettu cortu: qualchì dumanda, qualchì cosa à pruvà, un diamante viulettu o dui. Clic, accettatu, torna à u to caffè.","dl.windows":"App per Windows","dl.browser":"Eseguitela in u navigatore","dl.soon":"Prestu dispunibule","dl.notify":"🔔 Avvisami quandu s'apre","dl.notifySmall":"Alfa o beta","hero.secondary":"Agile, ma a squadra ùn hà mai bisognu di u caffè di a stand-up. (Face e stand-up listessu.)","pitch.h2":"AI-gile in tante parolle quant'è tù vo","pitch.lede":"Sceglie una lunghezza, da una parolla à 144. Ogni lunghezza hè una discrizzione propria, scritta per quella misura. Tira u cursore o usa e fraccette di a tastera.","pitch.rangeLabel":"Lunghezza in parolle","pitch.dice":"🎲 un'altra versione","pitch.words.one":"{n} parolla","pitch.words.other":"{n} parolle","pitch.letters.one":"{n} lettera","pitch.letters.other":"{n} lettere","pitch.chars.one":"{n} carattere","pitch.chars.other":"{n} caratteri","count.line.html.one":"{n} carta nantu à a tavula avà","count.line.html.other":"{n} carte nantu à a tavula avà","features.aria":"Ciò chì face","f.pile.h":"Un mucchjettu per tè","f.pile.html":"<b>Per tè</b> riunisce tuttu ciò chì ti aspetta, in tutti i prugetti: dumande, cose à pruvà, travagli chì solu una persona pò fà. A to fila dice cio chì vene dopu è quantu tempu ci vole.","f.sleep.h":"Squadre chì travaglianu mentre dorme","f.sleep.p":"Ogni prugettu hà un capu è una squadra d'agenti AI. Lascia un cumentu nantu à una carta è a squadra si sveglia, face u travagliu è ti u rende cù i passi chì pò seguità ancu una persona stanca.","f.tester.h":"Un tester AI verifica prima","f.tester.p":"Nanzu chì qualcosa ti ghjunghje, un tester seguita i passi in una copia di l'app è mostra ciò chì hà vistu, cù una cattura di schermu. Sfoglia quelle chì sò passate è accetta cù un clic.","f.proof.h":"Prove, micca prumesse","f.proof.p":"Ogni cunsegna mostra ciò chì hè cambiatu: i fugliali, e differenze, e catture di schermu. Ùn ci hè bisognu d'apre ogni app per sapè s'ellu hè compiu.","f.chat.h":"Chjachjerà cù i to capi","f.chat.p":"Una barra à u stilu di Discord: una icona per prugettu, diamanti viulettu per ciò chì ti vole. Manda una idea à un capu; a trasforma in carte è in un pianu, cù un buttone ✅ Go.","f.tidy.h":"Si tene in ordine solu","f.tidy.p":"E carte parenti si unisconu in una, i tituli imbrugliati sò currettati, è un cuntrollu di i token tene u codice leggeru. Menu cose trà e quali passà, menu à pensà.","f.private.h":"Toiu, nantu à u to urdinatore","f.private.li1":"A tavula gira nantu à a to macchina è risponde solu à tè.","f.private.li2":"I missaghji privati trà e persone sò cifrati da un capu à l'altru.","f.private.li3":"Nisun contu, nisun tracciatore, nisun cookie.","f.lang.h":"In a to lingua","f.lang.p":"Più di 120 lingue, da l'olandese, u gallese è u giapponese finu à u pirata, Yoda è u klingon, cù un cambiu prestu in inglese per e parolle di i sviluppatori.","tl.aria":"Cronologia da a prima cunversazione à u pianu di strada","tl.h2":"Da a prima chjachjarata à ciò chì vene dopu","tl.lede":"Date è ore vere, in u to fusu orariu. Dopu à oghje hè u pianu, senza date prumesse.","tl.today":"Oghje","tl.planned":"previstu","tl.cards.one":"{n} carta","tl.cards.other":"{n} carte","join.h2":"Unisciti","join.lede":"AI-gile hè custruitu da una persona chjuca è un gran numeru d'agenti pazienti. Hè privatu per avà, in una alfa chjosa cù l'amichi. Ti piacerebbe pruvallu quandu s'aprerà?","join.btn":"Signalà u to interessu","join.small":"Ti scriveremu un email, nunda più","footer.tag":"AI-gile. Nisun tracciatore, nisun cookie, nisun caffè di stand-up.","footer.licence":"Licenza d'impresa","footer.status":"Statu","footer.privacy":"Ciò chì guardemu","form.sending":"Mandu in corsu…","form.failed":"Ùn hà micca fattu: ripruva più tardi.","form.offline":"Impussibule di ghjunghje à AI-gile: ripruva più tardi.","form.keep":"L'usemu solu per risponde ti, po u scancellemu. Nisun tracciatore, nisun cookie.","form.keepLink":"Ciò chì guardemu","interest.title":"AI-gile: avvisami quandu s'apre l'alfa","interest.description":"Lascia u to email per sapè quandu s'apre l'alfa chjosa o a beta di AI-gile.","interest.h1":"🔔 Avvisami quandu s'apre","interest.lede":"AI-gile hè in pre-alfa chjosa. Lascia u to email è ti scriveremu una volta, quandu ci serà un locu per tè.","interest.email":"U to email","interest.which":"Quale prova?","interest.alpha":"Alfa chjosa: prestu, grezza, tanti cambiamenti","interest.beta":"Beta: più stabile, dopu","interest.both":"L'una o l'altra, quella chì vene prima","interest.submit":"Mettimi nantu à a lista","interest.thanks":"Grazie! Sì nantu à a lista.","licence.title":"AI-gile: licenza d'impresa","licence.description":"Usi AI-gile in a to impresa? Dumanda una licenza d'impresa gratuita.","licence.h1":"📜 Licenza d'impresa","licence.lede":"Usi AI-gile à u travagliu? Dicci quale sì è ciò chì faci. S'ellu face un pocu di bè, a licenza hè gratuita.","licence.company":"Impresa","licence.website":"Situ web","licence.what":"Ciò chì faci","licence.how":"Cumu aiuta u mondu","licence.email":"Email","licence.submit":"Dumandà","licence.thanks":"Grazie! Ti risponderemu per email.","status.title":"Statu di AI-gile","status.h1":"Statu di AI-gile","status.quiet":"Tuttu tranquillu","status.intro":"AI-gile funziona avà? Sta pagina verifica u situ, u spartimentu di e tavule, e chjamate è u scaricamentu ogni 5 minuti.","status.up":"Funziona (hà rispostu in {ms} ms)","status.slow":"Ùn hà micca rispostu à l'ultima verificazione, ripruvemu","status.down":"In panna: ùn hà micca rispostu à l'ultime duie verificazioni","status.svc.web":"Situ web","status.svc.web.offers":"Stu situ: ciò ch'ellu hè AI-gile, è u furmulariu d'interessu","status.svc.boards":"Spartimentu di e tavule","status.svc.boards.offers":"Tavule publiche, messaghji trà amichi è invitazioni","status.svc.calls":"Chjamate","status.svc.calls.offers":"Voce, video è spartimentu di screnu in AI-gile","status.svc.download":"Scaricamentu","status.svc.download.offers":"L'installatore Windows è i liami d'invitazione","status.checking":"Verificà in corsu…","status.offline":"Impussibule di ghjunghje à u serviziu di statu avà (ripruvemu)","status.updated":"aghjurnatu {ago}","status.justNow":"à l'istante","status.min":"{n} min fà","status.hours":"{n} o fà","status.days":"{n} g fà","privacy.title":"AI-gile: ciò chì guardemu","privacy.h1":"Ciò chì guardemu","privacy.lede":"In breve: solu ciò chì tù ci mandi, è micca per longu.","privacy.only":"Solu ciò chì tù ci mandi: ciò chì tù scrivi in un furmulariu, cum'è u to email. Nunda altru nant'à tè.","privacy.sealed":"Hè sigillatu cusì chì u nostru servitore ùn u pò leghje: in u to navigatore prima ch'ellu parti (nantu à un navigatore più vechju, appena ch'ellu ghjunghje). Solu a nostra propria tavula u pò apre.","privacy.server":"Hè scancellatu da u servitore appena ch'ellu ghjunghje à a nostra tavula. Tuttu ciò chì ci hè sempre dopu à 30 ghjorni hè scancellatu quantunque.","privacy.board":"U guardemu nantu à a nostra tavula solu finu à ch'è no t'avemu rispostu, po u scancellemu quallà dinù.","privacy.none":"Nisun tracciatore, nisun cookie, nisuna analitica.","privacy.local":"A to lingua è a to scelta chjara o scura fermanu in u to propiu navigatore. Ùn ci sò mai mandate.","privacy.ask":"U voli sparitu più prestu? Rispondi à u nostru email è dicci la.","live.h2":"Guardate cumu hè custruitu, in diretta","live.caption":"Ogni carta hè piatta: videte a forma di u travagliu, micca e parolle.","live.watching.one":"in diretta: {n} chì guardanu","live.watching.other":"in diretta: {n} chì guardanu","live.last.now":"L'ultima carta hè stata spostata ghjustu avà","live.last.min.one":"L'ultima carta hè stata spostata {n} min fà","live.last.min.other":"L'ultima carta hè stata spostata {n} min fà","live.last.hour.one":"L'ultima carta hè stata spostata {n} ora fà","live.last.hour.other":"L'ultima carta hè stata spostata {n} ore fà","live.last.day.one":"L'ultima carta hè stata spostata {n} ghjornu fà","live.last.day.other":"L'ultima carta hè stata spostata {n} ghjorni fà","live.offline":"U tavulone in diretta piglia un pocu di risu. Turnate prestu.","live.cols":"Backlog|À fà|In corsu|Verificazione di a squadra|Per tè da testà|Per a squadra|Fattu"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Delegatu."]},{"n":2,"texts":["Kanban robotica.","Agenti, urganizati.","Idee, custruite."]},{"n":3,"texts":["Kanban per robot.","Idee diventanu funzioni.","Kanban d'agenti gratuitu."]},{"n":5,"texts":["Tavula kanban guidata da agenti.","Tù scrivi carte. Agenti custruiscenu.","Gratuita, lucale, pruvata, un pocu scema."]},{"n":8,"texts":["Una tavula kanban gratuita induve travaglianu agenti AI.","Scrivi una idea. L'agenti a custruiscenu. Tù accetti.","Agile per una persona è tanti robot pazienti."]},{"n":13,"texts":["Una tavula kanban nantu à u to urdinatore induve l'agenti AI piglianu e carte.","Scrivi una idea. Una squadra d'agenti a custruisce. Un tester a verifica.","Gratuita, senza conti, senza tracciatori: una tavula, qualchì robot è tù à cumandà."]},{"n":21,"texts":["AI-gile hè una tavula kanban per travaglià cù agenti AI chì prugrammanu. Elli piglianu e carte; tù e pruvi è l'accetti.","Ogni prugettu hà un capu è una squadra d'agenti AI. Lascia un cumentu nantu à qualsiasi carta è a squadra si mette subitu à travaglià.","Una tavula persunale è gratuita, chì gira nantu à u to urdinatore. I travagliadori sò robot. Quellu chì dice iè sì tù."]},{"n":34,"texts":["Metti l'idee nantu à una tavula. Una squadra d'agenti AI e trasforma in funzioni chì marchjanu, e pruva è te e rende cù i passi per pruvalle. Nunda conta cum'è fattu finu à chì u dici tù.","AI-gile hè una tavula kanban fatta in casa chì Rich hà custruitu cù assai aiutu di l'agenti ch'ella gestisce oghje. Hè gratuita, gira nantu à u to urdinatore è hè spartuta cù l'amichi, micca venduta.","Imagina una tavula kanban nurmale, cù culonne da u Backlog à Fattu, ma induve e carte sò pigliate da agenti AI. Rapportanu l'avanzata, dumandanu quandu sò bluccati, è aspettanu sempre u to pollice in sù."]},{"n":55,"texts":["AI-gile hè una tavula kanban induve a squadra hè fatta d'agenti AI. Ogni prugettu hà un capu chì pianifica u travagliu è aiutanti chì u custruiscenu. Quandu una funzione hè pronta, un tester AI a pruva è face una cattura di schermu, poi ghjunghje in u to mucchjettu. Accettala, o lascia un cumentu è a rifaranu.","Hè natu cum'è u modu d'una persona di seguità parechje sessioni di prugrammazione AI à una volta, è hè criscutu finu à diventà una vera tavula. Gira nantu à a to macchina, ùn vole nisun contu, è ùn hà nisun tracciatore. Hè gratuita per l'amichi è i curiosi. Hè dinù incompiuta, dunque aspetta bordi grezzi è qualchì surpresa.","Eccu a versione onesta. Tù devi sempre avè l'idee, è devi sempre verificà i risultati. Ciò chì face AI-gile hè tuttu ciò chì ci hè trà i dui: tene e carte in ordine, sveglia l'agente ghjustu quandu lasci un cumentu, mostra esattamente ciò chì hè cambiatu, è mette tuttu in un mucchjettu cortu per tè."]},{"n":89,"texts":["AI-gile hè una tavula kanban gratuita chì fai girà nantu à u to propiu urdinatore. Invece di persone, ogni prugettu hà una squadra d'agenti AI: un capu chì trasforma e to idee in carte è in un pianu, è aiutanti chì piglianu e carte per ordine di prioriteta. Quandu qualcosa hè custruitu, un tester AI seguita i passi di prova è ti mostra ciò chì hà vistu. Poi aspetta in un mucchjettu chjamatu Per tè. L'accetti, o lasci un cumentu è a squadra pruva torna. Nunda ghjunghje mai à Fattu senza di tè.","Qualchì cosa chì forse ùn t'aspetti micca. Una guardia di notte tene piena a culonna À fà mentre dorme, sceglendu carte chì ùn anu bisognu d'una risposta da tè. Un cuntatore di token mostra quantu l'agenti anu adupratu oghje è sta settimana, è u No Token Mode li dice di piantà di spende. Pudi scrive à l'amichi, è i missaghji privati sò cifrati da un capu à l'altru. A tavula parla circa 120 lingue, cumprese l'olandese, u fiammingu, u pirata è u klingon. Nunda di tuttu què costa un centesimu, è nimu ùn prova à vendeti nunda.","AI-gile hè un picculu prugettu persunale, micca una sucietà. Rich vulia curà parechji prugetti di prugrammazione AI senza apre ogni app per verificalli, allora ellu è l'agenti anu custruitu una tavula per què, è dopu anu adupratu a tavula per custruisce u restu d'elli stessi. Hè in pre-alfa chjosa, chì vole dì ch'ella funziona, più o menu, per una manata d'amichi. Ùn ci hè pagina di prezzi, nè newsletter, nè pianu di crescita. S'ellu ti pare utile, pudi dumandà di pruvallu quandu s'aprerà un pocu di più."]},{"n":144,"texts":["AI-gile hè una tavula kanban per una persona è tanti agenti AI. Gira nantu à u to propiu urdinatore è hè compiamente gratuita. Aghjunghji prugetti, è ogni prugettu hà un capu è una squadra chjuca. Chjachjeri cù u capu, un pocu cum'è nantu à Discord, è discrivi una idea; u capu a trasforma in carte è in un pianu, poi aspetta ch'è tù prema Go. A squadra travaglia e carte per ordine di prioriteta, cù una linea di cumandi simplice fatta per i mudelli di lingua. Nanzu chì qualcosa ti torni, un tester AI seguita i passi in una copia di l'app è attacca una cattura di schermu. U travagliu compiu ghjunghje in u to mucchjettu cù i fugliali cambiati è a differenza. L'accetti, o lasci un cumentu è a squadra si sveglia è pruva torna. Solu tù pò spustà una carta in Fattu. Nisun contu, nisun tracciatore, nisun cookie, è tuttu stà nantu à u to urdinatore.","Una ghjurnata cù AI-gile, à pocu pressu. A sera lasci qualchì cumentu: stu buttone hè in u locu sbagliatu, quella lista duverebbe esse urdinata, puderiamu avè un modu scuru. Vai à durmite. L'agenti leghjenu i cumenti, facenu i cambiamenti, i pruvanu è i rendenu. Se À fà s'asciuga, a guardia di notte u riempie da u backlog cù carte chì ùn anu bisognu d'alcuna risposta da tè. À a mattina ci hè un mucchjettu cortu: una coppia di dumande è qualchì cosa à pruvà, ognuna cù passi chì pò seguità una persona insunnuliata è una cattura di schermu chì mostra ch'ella funziona. Clicchi, accetti e bone è rimandi u restu. Un cuntatore di token mostra ciò chì hà adupratu tuttu què, è u No Token Mode hè per e settimane magre. Poi fai colazione, chì l'agenti ùn ponu ancu aiutà à fà.","Prima, ciò chì AI-gile ùn hè micca. Ùn hè una startup, ùn hè in vendita, è nimu ùn raccoglie i to dati. Hè una tavula gratuita chì gira nantu à u to urdinatore, senza conti, senza tracciatori è senza cookie. Ciò ch'ella hè: un locu ordinatu per vede tutti i prugetti di prugrammazione AI à una volta, cù una squadra d'agenti chì face e carte è tù chì pigli e decisioni. Unisce e carte parenti, currege i tituli imbrugliati, è tene d'ochju quantu u codice firmeghja leggeru. Parla circa 120 lingue, da l'olandese è u fiammingu finu à u pirata è u klingon. L'amichi ponu scrivesi, in privatu è cifratu. Hè statu custruitu da Rich è un gran numeru d'agenti pazienti, soprattuttu aduprandusi. Hè in pre-alfa chjosa, dunque hè grezzu in certi lochi. S'ellu ti pare un spassu, dumanda cù gentilezza è forse entrerai prestu."]}],"quips":{"1":"Una parolla. Audace. Forse troppu audace.","3":"Trè parolle. Dighjà più onesta di a maiò parte di e pagine di prudotti.","8":"Ottu parolle. Sempre più corta d'una stand-up.","21":"E lunghezze sò story points, per via. Sicuru ch'elle sò.","55":"Cinquantacinque parolle. Dui carte sò state compie mentre leghji.","144":"Hè quella longa. Ùn ci hè 233. L'agenti sò andati à durmite."}},"timeline":{"first-idea.name":"A prima idea","first-idea.line":"A primissima cunversazione, nanzu ch'ellu esistessi qualsiasi codice.","first-board.name":"Prima tavula","first-board.line":"Una tavula chì seguita a so propria custruzzione: carte, culonne, tirà è lascià, prugetti.","team-roles.name":"Squadra è roli","team-roles.line":"Prufili d'agenti, mudelli di squadra, spazii è quale face ciò chì.","install.name":"Installazione è versioni","install.line":"Un zip chì un amicu pò installà, aghjurnamenti autumatichi, canali è ritornu in daretu.","usage-saver.name":"Risparmiu d'usu","usage-saver.line":"Misurà ciò chì costanu l'esecuzioni, tene u codice leggeru, risparmià u to limite.","friends.name":"Amichi è spartera","friends.line":"Missaghji privati, un relé cifratu, invitazioni, roli è prugetti spartuti.","languages.name":"Lingue","languages.line":"Ogni testu di schermu in un fugliale di lingua, cù l'olandese è u fiammingu prima.","ai-tester.name":"Tester AI","ai-tester.line":"Un tester verifica prima ogni cunsegna è mostra ciò chì hà vistu.","website.name":"U situ web","website.line":"aigile.lol, l'anteprima è sta cronologia.","streaming.name":"Chat è streaming","streaming.line":"Discord, Twitch, OBS, modu streamer, GIF è emoji.","no-ai.name":"Edizione senza AI","no-ai.line":"Una tavula per quelli chì prugrammanu senza AI, è tavule pubbliche.","night-watch.name":"Guardia di notte","night-watch.line":"Un guardianu è un Scrum Master tenenu e squadre à u travagliu mentre dorme.","p-more.name":"Tuttu u restu","p-more.line":"Idee più chjuche chì aspettanu sempre u so turnu.","p-android.name":"Telefonu è Android","p-android.line":"Ghjunghje à a to tavula da un telefonu, poi una app Android nativa.","p-release.name":"Alfa è oltre","p-release.line":"Alfa chjosa, u situ in diretta, poi a beta.","p-languages.name":"Più lingue","p-languages.line":"Più di centu lingue, è un modu d'immersione per quelli chì imparanu.","p-engines.name":"Più mutori AI","p-engines.line":"Sceglie Claude, Codex o Gemini per ogni agente.","p-pro.name":"Pratica prufessiunale","p-pro.line":"Etichette di risicu, porte di fusione, carte d'incidenti è paracarri.","p-self.name":"Curà di tè","p-self.line":"Modu stancu, rammentatori di cura di sè è 4:20.","p-servers.name":"Servitori è crescita","p-servers.line":"Paramettri glubali di i servitori, roli è pianificazione per crescere.","p-livestream.name":"Extra di streaming","p-livestream.line":"Chat di Twitch, emoji persunalizati è una vista pubblica in diretta."},"words":{"button":"📖 Parolle di sviluppatore","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Circà una parolla…","none":"Nisuna parolla currisponde.","close":"Chjode","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"U cartulare di u prughjettu cù u codice è tutta a storia di i commit, spessu tenutu ancu nantu à GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Una linea di travagliu à parte in u codice, per pudè fà cambiamenti senza tuccà a versione principale.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Una istantanea salvata di u codice, cù una nota corta di ciò chì hè cambiatu. Pudi sempre turnà à una.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Mandà l'istantanee salvate (commits) da stu urdinatore à GitHub, perchè sianu salvate è sparte."},{"id":"merge","g":"build","word":"Merge","text":"Riunisce i cambiamenti d'una branch in a versione principale."},{"id":"pr","g":"build","word":"Pull request","text":"Dumandà chì i cambiamenti d'una branch sianu verificati è fusi in a versione principale.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Mette in ordine u codice senza cambià ciò chì face : schedarii più chjuchi, nomi più chjari, menu ripetizioni."},{"id":"bug","g":"build","word":"Bug","text":"Qualcosa chì ùn funziona micca cum'ellu duverebbe.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Pruvà un travagliu finitu per verificà chì face ciò chì era statu dumandatu, nanzu di accettallu.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Mette una versione nova in linea, per esempiu nantu à un servitore induve a ghjente a usa."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Idee è travagliu micca ancu pianificati. Nunda quì hè travagliatu finu à chì passa in À fà."},{"id":"sprint","g":"team","word":"Sprint","text":"Un cortu periodu di travagliu (spessu una o duie settimane) cù un inseme di carte cunvenutu da compie.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Un puntu prestu : ciò chì ogni membru hà fattu, ciò chì face dopu, è ciò chì u ferma.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Una tavula cù colonne (À fà, In corsu, Fattu) induve e carte vanu da manca à diritta mentre u travagliu avanza."},{"id":"wip","g":"team","word":"Limite WIP","text":"Work in progress : u massimu di carte chì una colonna deve tene, perchè a squadra compii e cose nanzu di principià ne di più.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agente","text":"Una IA chì travaglia da sola nantu à un compitu : leghje u codice, face cambiamenti, eseguisce verificazioni, è ti torna rapportu.","also":["agenti"]},{"id":"token","g":"team","word":"Token","text":"L'unità in a quale l'usu di l'IA hè cuntatu : à pocu pressu uni pochi di lettere di testu lette o scritte. Menu token, più pianu chì ferma.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Una cumanda chjuca chì gira da sè à un mumentu datu, p.e. quandu una sessione IA principia, perchè a squadra senti i to cummenti.","also":["hooks"]}]}};
